    shape = [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row)
             if v != bg and v != marker]
    mpos = (next(iter({i for i, _ in mcells})) if horizontal
            else next(iter({j for _, j in mcells})))
    s = [i for i, _ in shape] if horizontal else [j for _, j in shape]
    near_edge = max(s) if mpos > max(s) else min(s)
    target = mpos - 1 if mpos > max(s) else mpos + 1
    shift = target - near_edge
    far = (min(s) if mpos > max(s) else max(s)) + shift
    far += -1 if mpos > max(s) else 1
    out = [[bg] * len(grid[0]) for _ in grid]
    dr = shift if horizontal else 0
    dc = shift if not horizontal else 0
    for i, j in shape:
        out[i + dr][j + dc] = grid[i][j]
    draw_line(out, far, color, 'h' if horizontal else 'v')
    for i, j in mcells:
        out[i][j] = marker
    return out

