def wave_fill_right(grid, fill=1):
    cnt=Counter(v for r in grid for v in r)
    bg=cnt.most_common(1)[0][0]
    mk=[c for c in cnt if c!=bg][0]
    H,W=len(grid),len(grid[0])
    rmv=[max([c for c,v in enumerate(row) if v==mk],default=-1) for row in grid]
    parent={}
    def find(a):
        while parent[a]!=a: parent[a]=parent[parent[a]]; a=parent[a]
        return a
    def union(a,b):
        ra,rb=find(a),find(b)
        if ra!=rb: parent[ra]=rb
    for i in range(H):
        for j in range(W):
            if grid[i][j]==mk:
                parent.setdefault((i,j),(i,j))
                for dr,dc in ((1,0),(0,1)):
                    a,b=i+dr,j+dc
                    if a<H and b<W and grid[a][b]==mk:
                        parent.setdefault((a,b),(a,b)); union((i,j),(a,b))
    comps={}
    for cell in parent: comps.setdefault(find(cell),[]).append(cell)
    cmax={}; tiprows={}
    for cells in comps.values():
        cm=max(c for _,c in cells)
        cmax[id(cells)]=cm
    info={}
    for root,cells in comps.items():
        cm=max(c for _,c in cells)
        info[root]=(cm, sorted(set(r for r,c in cells if c==cm)))
    out=[list(r) for r in grid]
    rootof={cell:find(cell) for cell in parent}
    for i in range(H):
        if rmv[i]<0: continue
        root=rootof[(i,rmv[i])]
        cm,tiprows=info[root]
        fire = rmv[i]==cm or (i-1 in tiprows and rmv[i]==cm-1)
        if not fire: continue
        tiprow = i if rmv[i]==cm else i-1
        solid = (rmv[i]>0 and grid[i][rmv[i]-1]==mk) or (tiprow>0 and grid[tiprow-1][cm]==mk)
