            else next(iter({j for _, j in mcells})))
    s = [i for i, _ in shape] if horizontal else [j for _, j in shape]
    near_edge = max(s) if mpos > max(s) else min(s)
    target = mpos - 1 if mpos > max(s) else mpos + 1
    shift = target - near_edge
