def fill_periodic_stripes(grid):
    """Fill background cells so colors are constant on (col - row) mod p diagonals, choosing the smallest consistent period p."""
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    known = [(i, j, grid[i][j]) for i in range(h) for j in range(w) if grid[i][j] != bg]
    period = None
    for p in range(1, w + 1):
        groups = {}
        ok = True
        for i, j, v in known:
            d = (j - i) % p
            if d in groups and groups[d] != v:
                ok = False
                break
            groups[d] = v
        if ok:
            period = p
            break
    out = [row[:] for row in grid]
    if period is None:
        return out
    groups = {}
    for i, j, v in known:
        groups.setdefault((j - i) % period, v)
    for i in range(h):
        for j in range(w):
            if out[i][j] == bg and (j - i) % period in groups:
                out[i][j] = groups[(j - i) % period]
    return out



def overlap_half(grid, fill=2, bg=0):
