            for lr, rr in zip(grid, [row[right0:] for row in grid])]



def fill_ring_interiors(grid, fill_even=2, fill_odd=7):
    """Fill the background interior of each rectangular single-color ring with `fill_even` if the interior side is even, else `fill_odd`."""
    bg = background(grid)
    out = [row[:] for row in grid]
    for comp in components(grid):
        rs = [r for r, _ in comp]; cs = [c for _, c in comp]
        t, l, b, r = min(rs), min(cs), max(rs), max(cs)
        if len(comp) != 2 * (b - t + 1) + 2 * (r - l - 1) or b - t < 2 or r - l < 2:
            continue  # not a full rectangular ring
        border_color = grid[t][l]
        if any(grid[i][j] != border_color for i, j in comp):
            continue
        side = b - t - 1  # interior is square in all examples
        fill = fill_even if side % 2 == 0 else fill_odd
        for i in range(t + 1, b):
            for j in range(l + 1, r):
                if out[i][j] == bg:
