def downscale_block(grid, size, ignore=(0,)):
    """Downscale by taking `size`x`size` blocks; each block becomes the most common color not in `ignore`, or 0 if none."""
    h, w = len(grid), len(grid[0])
    out = []
    for bi in range(0, h - size + 1, size):
