        for bj in range(0, w - size + 1, size):
            vals = [grid[i][j] for i in range(bi, bi + size) for j in range(bj, bj + size)
                    if grid[i][j] not in ignore]
            row.append(Counter(vals).most_common(1)[0][0] if vals else 0)
        out.append(row)
    return out

